def arrivals(s, jv, dmax, lam=None):
    """r_d = A^d 1 (A[dst,src]); if lam is given the operator is A/lam."""
    v = jv if lam is None else jv / lam
    x = np.ones(s["n"])
    out = {}
    for d in range(1, dmax + 1):
        y = np.zeros(s["n"])
        np.add.at(y, s["rows"], v * x[s["cols"]])
        x = y
        out[d] = x.copy()
    return out
